 function text(v){if(v==null)return '未定';if(v===true)return '是';if(v===false)return '否';if(typeof v==='number')return String(n(v));if(typeof v!=='object')return String(v);if(Array.isArray(v))return v.map(text).join(',');const rendered=Object.entries(v).filter(([k,z])=>z!==undefined&&!meta.has(k)).map(([k,z])=>(labels[k]||k)+'='+text(z)).join(';');if(sharedFragments&&rendered.length>=120)sharedFragments.set(rendered,(sharedFragments.get(rendered)||0)+1);return rendered;}
