 function encodeSpecialPointVargas(value){
  if(!value)return value;
  function encode(map){
   const divisions=Object.keys(map||{}),points=Object.keys(map?.[divisions[0]]||{}),signNames={};
   for(const d of divisions){if(Object.keys(map[d]).join('\0')!==points.join('\0'))return map;
    for(const k of points){const p=map[d][k];if(Object.keys(p).sort().join(',')!=='division,house,part,sign,signName'||p.division!==Number(d)||signNames[p.sign]!==undefined&&signNames[p.sign]!==p.signName)return map;signNames[p.sign]=p.signName;}
   }
   return {$vargaPoints:{divisions,points,signNames,rows:divisions.map(d=>points.map(k=>{const p=map[d][k];return [p.sign,p.part,p.house];}))}};
  }
  return {...value,specialLagnas:encode(value.specialLagnas),lagnaVariants:encode(value.lagnaVariants),upagrahas:encode(value.upagrahas),upagrahaVariants:Object.fromEntries(Object.entries(value.upagrahaVariants||{}).map(([k,v])=>[k,encode(v)]))};
 }
